            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) != 2 or len(bands[0]) != len(bands[1]):
        return [row[:] for row in grid]
    first, second = bands
    width = len(grid[0])
    shifts = range(-min(5, width - 1), min(5, width - 1) + 1)
    def score(s):
        total = 0
        for a, b in zip(first, second):
            for c in range(width):
                source_c = c - s
                if 0 <= source_c < width and grid[b][c] == grid[a][source_c]:
                    total += 1
        return total
    shift = max(shifts, key=lambda s: (score(s), -abs(s)))
    edge_first = max(c for r in first for c, v in enumerate(grid[r]) if v != bg)
    edge_second = max(c for r in second for c, v in enumerate(grid[r]) if v != bg)
